			function doList(psStatus){

			    var grdList = app.lookup("grdList");
			    for(var i=3; i<grdList.columnCount-1; i++){
			        grdList.columnVisible(i, false);
			    }
			    
			    var deptCd = app.lookup("dmSearch").getValue("DEPT_CD");
			    
			    if (deptCd == "324") {  // 사이버상담 
			        for(var i=3; i<10; i++){
			            grdList.columnVisible(i, true);
			        }
			    }else if(deptCd == "325") {  // 사이버아웃리치
			        grdList.columnVisible(6, true);
			        grdList.columnVisible(10, true);
			        grdList.columnVisible(11, true);
			    }else if(deptCd == "326") {  // 모바일상담
			        for(var i=12; i<17; i++){
			            grdList.columnVisible(i, true);
			        }
			    }else{
			        for(var i=3; i<grdList.columnCount-1; i++){
			            grdList.columnVisible(i, true);
			        }
			    }
				//조회 서브미션 호출
				util.Submit.send(app, "subList", function(pbSuccess){
					if(pbSuccess) {
						if(psStatus == "save"){
							//갱신된 데이터가 조회되었습니다.
							util.Msg.notify(app, "INF-M005");
						}else{
							//조회되었습니다.
							util.Msg.notify(app, "INF-M001");
						}
					}
				});
			}

